/**
 * Las preguntas de casos de la vida real que agregó la revisión del sistema de estudio (docs/academia-auditoria.md) al
 * banco del examen final de cada materia ya publicada: el alumno aplica, analiza o evalúa lo aprendido en una situación
 * de la iglesia, la familia, el trabajo o la comunidad (2 por materia en el Nivel 1, 4 en el 2 y 6 en los demás). Cada
 * una se comprobó como los esquemas (redacción y doble verificación). index.ts las suma al banco del final. Por id de
 * materia; los ids terminan en «-caso-N» y nunca se reusan.
 */
