      leccion: 5,
      objetivo: "o5",
      bloom: "aplicar",
      texto: "Una familia de tu iglesia tuvo que mudarse a otra ciudad por falta de trabajo. Están tristes porque sienten que dejan atrás su ministerio. ¿Qué principio de Hechos 1 al 12 les ayuda más a ver su nueva situación?",
      correcta: "Que, como los esparcidos por la persecución, pueden anunciar el evangelio y servir en una iglesia donde lleguen",
