      bloom: "aplicar",
      texto: "En el equipo de alabanza de tu iglesia, dos integrantes discuten porque ambos quieren dirigir los cantos principales, y el resto del grupo se molesta con ellos. Tú coordinas el equipo. Según Marcos 10:35-45, ¿qué respuesta sigue mejor el ejemplo de Jesús?",
      correcta: "Usar la discusión para enseñarles que en el reino de Dios el grande es el que sirve a los demás",
