      explica: "Cuando Santiago y Juan pidieron los primeros lugares y los diez se enojaron, Jesús no repartió puestos: usó la discusión para enseñar que entre los suyos el grande es el servidor, porque él vino a servir y a dar su vida en rescate (Marcos 10:41-45).",
