      explica: "Pablo pide que el líder sea irreprensible, no codicioso de ganancias deshonestas y con buen testimonio de los de afuera, para que no caiga en descrédito (1 Timoteo 3:2-3, 7). Primero debe restaurar su testimonio: sin integridad se pierde la confianza (Proverbios 11:3).",
