      explica: "Vanidad significa vapor: el Predicador muestra que la vida vista solo bajo el sol no llena. Pero el libro no termina ahí: llama a temer a Dios y guardar sus mandamientos, porque Dios traerá toda obra a juicio (Eclesiastés 12:13-14; 11:9).",
