      objetivo: "o3",
      bloom: "aplicar",
      texto: "Un hermano de tu iglesia salió del hospital después de semanas en que todos oraron por él. El domingo la congregación quiere contar en el culto lo que Dios hizo, y el líder de alabanza te pide un salmo para leer. ¿Cuál es el más adecuado según los tipos de salmos?",
