      texto: "Un hermano trabajador y fiel quedó sin empleo cuando cerró la fábrica donde trabajaba. Alguien de la iglesia le dice: si de verdad fueras diligente, estarías prosperando, porque Proverbios dice que la mano de los diligentes enriquece. ¿Cómo evalúas ese comentario?",
