      explica: "Proverbios 10:4 enseña lo que normalmente sucede: la mano negligente empobrece y la diligente enriquece. Pero los proverbios son principios generales, no promesas automáticas, y acusar al que sufre repite el error de los amigos de Job (Job 42:7).",
