      texto: "Un compañero de trabajo te dice que Jesús conocía las profecías y se las arregló para cumplirlas. ¿Cuál de estos cumplimientos responde mejor a su objeción, porque no dependía de lo que Jesús decidiera hacer?",
      correcta: "Nacer en Belén de Judea, como lo había anunciado Miqueas 5:2, según lo cuenta Mateo 2:1-6",
