      explica: "Pablo pregunta si hemos de perseverar en el pecado para que la gracia abunde, y responde: en ninguna manera, porque morimos al pecado (Romanos 6:1-2). La libertad no es ocasión para la carne, sino para servir por amor y andar en el Espíritu (Gálatas 5:13, 16).",
