      explica: "Algunos en Corinto negaban la resurrección (1 Corintios 15:12). Pablo la pone en el corazón del evangelio: Cristo murió, fue sepultado y resucitó al tercer día (1 Corintios 15:3-4); y si no resucitó, vanas son la predicación y la fe (1 Corintios 15:14, 17).",
      ref: "1 Corintios 15:12-17",
