      texto: "Tu iglesia busca a alguien para un cargo de liderazgo. El candidato más popular predica con mucho talento, pero se convirtió hace pocos meses y en su casa hay un desorden que todos conocen. Según las cartas pastorales, ¿qué conviene hacer?",
