      texto: "Para predicar 2 Samuel 12:1-13, un pastor quiere contar primero la historia del rico y la corderita sin decir su idea, y dejar la confrontación para el final. ¿Qué forma de sermón elige, y encaja con el pasaje?",
      correcta: "Inductiva, y encaja: Natán cuenta primero la historia y solo después dice a David que él es aquel hombre",
