      texto: "Una compañera de trabajo te cuenta que un predicador le prometió que, si da una ofrenda especial de cierta cantidad, Dios le perdonará un pecado grave de su pasado. ¿Qué respuesta refleja mejor lo que recuperó la Reforma?",
