      explica: "Trento puso la tradición a la par de la Escritura; la Reforma afirmó que la Biblia es la autoridad final. Jesús reprochó invalidar la palabra de Dios con la tradición (Marcos 7:13), y los de Berea examinaban todo con las Escrituras (Hechos 17:11). Se responde con mansedumbre (1 Pedro 3:15).",
