      explica: "Wesley predicó al aire libre durante décadas, y los grupos metodistas cuidaron a miles de nuevos creyentes. Así hizo la iglesia de Jerusalén: los que recibieron la palabra perseveraban en la doctrina de los apóstoles, en la comunión y en las oraciones (Hechos 2:41-42).",
