      explica: "Pablo mismo se hace esa pregunta en 6:1, justo después de 5:20, y responde que en ninguna manera: el que murió al pecado no puede seguir viviendo en él. El bautismo muestra la unión con Cristo en su muerte y su resurrección, para andar en vida nueva (6:2-4, 11).",
