      leccion: 4,
      objetivo: "o4",
      bloom: "analizar",
      texto: "Después de leer sobre el avivamiento de Gales, un líder propone copiar en su iglesia el mismo horario, los mismos himnos y el mismo estilo de reuniones, seguro de que así llegará el avivamiento. ¿Qué análisis hace la lección?",
      correcta: "Los avivamientos se parecen porque el Señor no cambia, no porque se copien sus formas",
