      explica: "El Señor es el mismo ayer, hoy y por los siglos (Hebreos 13:8): por eso los avivamientos comparten oración perseverante, predicación de la Palabra, convicción de pecado, santidad, gozo y misión. La historia enseña esos caminos de Dios, no un molde que lo obligue.",
