      texto: "En unas reuniones de oración algunos lloran a gritos y otros tiemblan. A la vez, varios han dejado vicios, se han reconciliado, leen la Biblia con hambre y hablan más de Cristo. Un diácono pide suspenderlo todo por los gritos. ¿Qué evaluación hace la lección?",
