      objetivo: "o1",
      bloom: "analizar",
      texto: "En tu iglesia, los ujieres discuten cada domingo por quién atiende la puerta principal. El encargado hizo una lista de turnos y nada más, pero al mes las discusiones seguían, ahora por otras cosas. Según el método del seminario, ¿qué le faltó preguntarse?",
