      explica: "El método distingue el síntoma del problema de fondo: lo que se ve suele ser un síntoma. El corazón guarda intenciones profundas que el entendido sabe sacar (Proverbios 20:5); por eso se escucha a cada parte antes de decidir (Proverbios 18:17).",
