      explica: "En Hechos 15 los apóstoles y los ancianos se reunieron para conocer del asunto (15:6), oyeron a las partes, vieron lo que decían los profetas (15:15-17), buscaron lo que pareció bien al Espíritu Santo (15:28) y comunicaron la decisión por carta y de palabra (15:27).",
