      texto: "Después de una venta de comida para el campamento, el líder de jóvenes cuenta solo el dinero y lo guarda en su casa toda la semana. Nadie sospecha de él, pero el pastor quiere aplicar lo aprendido en el caso del dinero faltante. ¿Qué es lo más sabio?",
