      texto: "Tu iglesia solo puede abrir una obra nueva este año: en un barrio cercano que ya tiene cinco iglesias evangélicas, o en un pueblo de la región donde no hay ninguna iglesia ni testimonio de Cristo. Según la estrategia de Pablo, ¿qué decisión es la más acertada?",
      correcta: "Elegir el pueblo donde Cristo no ha sido nombrado, para no edificar sobre fundamento ajeno.",
