      texto: "A tu iglesia empiezan a llegar familias de otra lengua y cultura. Un líder propone que dejen su idioma y sus cantos para integrarse; otro, que se reúnan aparte para no incomodar a los de siempre. Según Apocalipsis 7:9-10, ¿qué respuesta es la más fiel?",
      correcta: "Acogerlas en un mismo pueblo, porque ante el Cordero se reúnen adoradores de todas las naciones.",
