        "Pedirles que dejen su idioma y sus cantos para integrarse, porque la unidad exige una sola cultura en la iglesia.",
        "Pedirles que se reúnan aparte, para que no incomoden a los miembros de siempre de la iglesia.",
        "Esperar a que aprendan bien el idioma de la iglesia antes de invitarlas a participar en ella.",
